  "ev.hsn6": "ᱟᱭᱴᱮᱢ {n}: ᱤ-ᱤᱱᱵᱷᱚᱭᱮᱥ ᱨᱮ 6 ᱥᱮ 8 ᱮᱞ ᱨᱮᱭᱟᱜ HSN/SAC ᱠᱳᱰ ᱞᱟᱹᱠᱛᱤ (4 ᱮᱞ ᱫᱚ ₹5 ᱠᱚᱴᱤ ᱠᱷᱚᱱ ᱠᱚᱢ ᱵᱤᱡᱤᱱᱮᱥ ᱞᱟᱹᱜᱤᱫ ᱜᱮ, ᱚᱠᱟ ᱤ-ᱤᱱᱵᱷᱚᱭᱮᱥ ᱵᱟᱝ ᱠᱚ ᱵᱮᱱᱟᱣᱟ)᱾",
  "ev.old30": "ᱱᱚᱶᱟ ᱤᱱᱵᱷᱚᱭᱮᱥ 30 ᱥᱮ ᱵᱟᱹᱲᱛᱤ ᱫᱤᱱ ᱢᱟᱨᱮ᱾ ₹10 ᱠᱚᱴᱤ ᱥᱮ ᱵᱟᱹᱲᱛᱤ ᱴᱟᱨᱱᱚᱵᱷᱟᱨ ᱨᱮ ᱯᱚᱨᱴᱟᱞ ᱱᱚᱶᱟ ᱫᱚ ᱱᱤᱛ ᱵᱟᱝ ᱨᱮᱡᱤᱥᱴᱟᱨᱟ᱾ ᱱᱟᱶᱟ ᱤᱱᱵᱷᱚᱭᱮᱥ ᱵᱮᱱᱟᱣ ᱞᱟᱦᱟ ᱟᱢᱟᱜ ᱮᱠᱟᱣᱩᱱᱴᱮᱱᱴ ᱠᱩᱞᱤ ᱢᱮ᱾",
  "ev.lt5": "ᱤ-ᱤᱱᱵᱷᱚᱭᱮᱥ ᱟᱢ ᱞᱟᱹᱜᱤᱫ ᱡᱚᱨᱩᱨᱤ ᱵᱟᱝ ᱠᱟᱱᱟ, ᱡᱩᱫᱤ 2017-18 ᱠᱷᱚᱱ ᱡᱟᱦᱟᱸ ᱥᱮᱨᱢᱟ ᱟᱢᱟᱜ ᱴᱟᱨᱱᱚᱵᱷᱟᱨ ₹5 ᱠᱚᱴᱤ ᱵᱟᱝ ᱯᱟᱨᱚᱢ ᱟᱠᱟᱱᱟ᱾",
  "ev.old180": "180 ᱫᱤᱱ ᱠᱷᱚᱱ ᱢᱟᱨᱮ ᱰᱚᱠᱭᱩᱢᱮᱱᱴ ᱨᱮᱭᱟᱜ ᱤ-ᱣᱮ ᱵᱤᱞ ᱯᱚᱨᱴᱟᱞ ᱵᱟᱝ ᱵᱮᱱᱟᱣᱟ᱾",
  "ev.smallst": "{st} ᱵᱷᱤᱛᱨᱤ ᱨᱮ ᱤ-ᱣᱮ ᱵᱤᱞ ᱥᱟᱫᱷᱟᱨᱚᱬ ᱛᱮ ₹{v} ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱨᱮ ᱜᱮ ᱞᱟᱹᱠᱛᱤ (ᱮᱴᱟᱜ ᱯᱚᱱᱚᱛ ᱨᱮ ₹50,000 ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ; ᱮᱴᱟᱜ ᱯᱚᱱᱚᱛ ᱪᱟᱞᱟᱜ ᱡᱚᱵ ᱣᱟᱨᱠ ᱟᱨ ᱦᱟᱛ ᱠᱟᱹᱢᱤ ᱨᱮ ᱡᱟᱦᱟᱸ ᱜᱚᱱᱚᱝ ᱨᱮ ᱞᱟᱹᱠᱛᱤ)᱾",
  "ev.fromirn": "ᱡᱩᱫᱤ ᱟᱢᱟᱜ ᱵᱤᱡᱤᱱᱮᱥ ᱤ-ᱤᱱᱵᱷᱚᱭᱮᱥ ᱵᱮᱱᱟᱣ ᱞᱟᱹᱠᱛᱤ ᱠᱟᱱᱟ, ᱱᱚᱶᱟ ᱤᱱᱵᱷᱚᱭᱮᱥ ᱨᱮᱭᱟᱜ ᱤ-ᱣᱮ ᱵᱤᱞ ᱯᱚᱨᱴᱟᱞ ᱱᱚᱣᱟ ᱨᱮᱭᱟᱜ IRN ᱠᱷᱚᱱ ᱜᱮ ᱵᱮᱱᱟᱣᱟ: “ᱤ-ᱤᱱᱵᱷᱚᱭᱮᱥ ᱥᱟᱶ ᱤ-ᱣᱮ ᱵᱤᱞ ᱦᱚᱸ ᱵᱮᱱᱟᱣ ᱢᱮ” ᱨᱮ ᱴᱤᱠ ᱢᱮ ᱟᱨ ᱤ-ᱤᱱᱵᱷᱚᱭᱮᱥ ᱯᱷᱟᱭᱤᱞ ᱵᱮᱱᱟᱣ ᱢᱮ᱾",
  "ev.tidchk": "ᱴᱨᱟᱱᱥᱯᱚᱨᱴᱟᱨ ID ᱨᱮᱭᱟᱜ ᱢᱩᱪᱟᱹᱫ ᱟᱠᱷᱚᱨ ᱵᱟᱝ ᱢᱤᱞᱟᱹᱣᱜ ᱠᱟᱱᱟ᱾ ᱴᱟᱭᱤᱯᱤᱝ ᱵᱷᱩᱞ ᱠᱟᱱᱟ ᱥᱮ, ᱢᱤᱫ ᱫᱷᱟᱣ ᱧᱮᱞ ᱢᱮ᱾",
  "ei.rmnote": "ᱡᱩᱫᱤ ᱟᱢ ᱱᱚᱶᱟ IRN ᱯᱚᱨᱴᱟᱞ ᱨᱮ ᱠᱮᱱᱥᱮᱞ ᱞᱮᱫᱟᱢ, ᱱᱚᱶᱟ ᱤᱱᱵᱷᱚᱭᱮᱥ ᱱᱚᱢᱵᱚᱨ ᱫᱚ ᱫᱚᱦᱲᱟ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱝ ᱨᱮᱡᱤᱥᱴᱟᱨᱚᱜᱼᱟ᱾ ᱴᱷᱤᱠ ᱤᱱᱵᱷᱚᱭᱮᱥ ᱱᱟᱶᱟ ᱱᱚᱢᱵᱚᱨ ᱛᱮ ᱵᱮᱱᱟᱣ ᱢᱮ᱾",
  /* tax rule fixes, bills (4 Nov 2026) */
