  "v.b2c": "GSTIN ᱵᱟᱹᱱᱩᱜ ᱠᱟᱥᱴᱚᱢᱟᱨ ᱮ ₹50,000 ᱥᱮ ᱵᱟᱹᱲᱛᱤ ᱵᱤᱞ ᱨᱮ GST ᱱᱤᱭᱚᱢ ᱞᱮᱠᱟᱛᱮ ᱠᱟᱥᱴᱚᱢᱟᱨ ᱨᱮᱭᱟᱜ ᱧᱩᱛᱩᱢ, ᱴᱷᱤᱠᱬᱟ ᱟᱨ ᱯᱚᱱᱚᱛ ᱞᱟᱹᱠᱛᱤ᱾",
  "c.r28": "1 ᱯᱷᱮᱵᱽᱨᱩᱣᱟᱨᱤ 2026 ᱠᱷᱚᱱ 28% GST ᱚᱪᱚᱜ ᱮᱱᱟ (ᱚᱱᱟ ᱡᱤᱱᱤᱥ ᱫᱚ ᱱᱤᱛ 40% ᱥᱮ 18% ᱨᱮ)᱾ ᱛᱮᱦᱮᱸᱱ ᱦᱚᱸ 28% ᱥᱟᱶ ᱥᱮᱵᱷ ᱦᱩᱭᱩᱜ ᱟ?",
  "c.cash2l": "ᱤᱱᱠᱟᱢ ᱴᱮᱠᱥ ᱟᱹᱭᱤᱱ ᱨᱮ ᱢᱤᱫ ᱵᱤᱞ ᱞᱟᱹᱜᱤᱫ ₹2 ᱞᱟᱠᱷ ᱥᱮ ᱵᱟᱹᱲᱛᱤ ᱱᱚᱜᱚᱫ ᱦᱟᱛᱟᱣ ᱢᱟᱱᱟ (ᱡᱚᱨᱤᱢᱟᱱᱟ ᱚᱛᱟᱠ ᱜᱮ)᱾ ᱛᱮᱦᱮᱸᱱ ᱦᱚᱸ ᱥᱮᱵᱷ ᱦᱩᱭᱩᱜ ᱟ?",
  /* Phase 1 additions */
  "v.orig": "ᱱᱚᱶᱟ ᱱᱚᱴ ᱡᱟᱦᱟᱸ ᱤᱱᱵᱷᱚᱭᱮᱥ ᱞᱟᱹᱜᱤᱫ ᱠᱟᱱᱟ, ᱚᱱᱟ ᱨᱮᱭᱟᱜ ᱱᱚᱢᱵᱚᱨ ᱟᱨ ᱛᱟᱨᱤᱠ ᱚᱞ ᱢᱮ᱾ GST ᱱᱤᱭᱚᱢ ᱞᱮᱠᱟ ᱱᱚᱴ ᱨᱮ ᱱᱚᱶᱟ ᱞᱟᱹᱠᱛᱤ ᱠᱟᱱᱟ᱾",
  "v.naddr": "GSTIN ᱵᱟᱹᱱᱩᱜ ᱜᱨᱟᱦᱟᱠ ᱞᱟᱹᱜᱤᱫ ᱚᱱᱟ ᱨᱮᱭᱟᱜ ᱴᱷᱤᱠᱟᱹᱱᱟ ᱟᱨ ᱨᱟᱡᱽ ᱚᱞ ᱢᱮ᱾",
  "c.cn30": "ᱱᱚᱶᱟ ᱠᱨᱮᱰᱤᱴ ᱱᱚᱴ ᱨᱮᱭᱟᱜ ᱛᱟᱨᱤᱠ ᱫᱚ ᱚᱱᱟ ᱤᱱᱵᱷᱚᱭᱮᱥ ᱨᱮᱭᱟᱜ ᱯᱷᱟᱭᱤᱱᱟᱱᱥᱤᱭᱟᱞ ᱤᱭᱟᱨ ᱢᱩᱪᱟᱹᱫ ᱛᱟᱭᱚᱢ 30 ᱱᱚᱵᱷᱮᱢᱵᱟᱨ ᱠᱷᱚᱱ ᱛᱟᱭᱚᱢ ᱠᱟᱱᱟ (ᱥᱮ ᱚᱱᱟ ᱥᱮᱨᱢᱟ ᱨᱮᱭᱟᱜ ᱮᱱᱩᱣᱟᱞ ᱨᱤᱴᱚᱨᱱ ᱯᱷᱟᱭᱤᱞ ᱛᱟᱭᱚᱢ, ᱡᱩᱫᱤ ᱚᱱᱟ ᱢᱟᱲᱟᱝ ᱦᱩᱭ ᱠᱷᱟᱱ)᱾ ᱚᱱᱟ ᱛᱟᱨᱤᱠ ᱛᱟᱭᱚᱢ ᱚᱱᱟ ᱨᱮᱭᱟᱜ GST ᱵᱟᱝ ᱠᱚᱢᱚᱜᱼᱟ (ᱵᱤᱡᱱᱮᱥ ᱰᱚᱠᱭᱩᱢᱮᱱᱴ ᱞᱮᱠᱟᱛᱮ ᱱᱚᱴ ᱫᱚ ᱴᱷᱤᱠ ᱜᱮ)᱾ ᱛᱚᱵᱮ ᱦᱚᱸ ᱥᱮᱣ ᱢᱮ?",
  "s.tds": "ᱴᱟᱠᱟ ᱮᱢᱤᱡ ᱛᱮ ᱠᱟᱴᱟᱣ TDS (₹)",
  "s.h.tds": "ᱴᱟᱠᱟ ᱮᱢᱤᱡ TDS ᱠᱟᱴᱟᱣ ᱞᱮᱱ ᱠᱷᱟᱱ ᱜᱮ᱾ ᱨᱚᱥᱤᱫ ᱨᱮ TDS ᱟᱨ ᱪᱩᱠᱛᱟ ᱟᱠᱟᱱ ᱯᱩᱨᱟᱹ ᱵᱤᱞ ᱴᱟᱠᱟ ᱩᱫᱩᱜᱚᱜᱼᱟ᱾",
  "c.cash10k": "ᱤᱱᱠᱟᱢ ᱴᱮᱠᱥ ᱟᱹᱭᱤᱱ ᱨᱮ ᱢᱤᱫ ᱦᱚᱲ ᱠᱮ ᱢᱤᱫ ᱫᱤᱱ ᱨᱮ ₹10,000 ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱱᱚᱜᱚᱫ ᱯᱮᱢᱮᱱᱴ ᱫᱚ ᱵᱤᱡᱱᱮᱥ ᱠᱷᱚᱨᱚᱪ ᱞᱮᱠᱟᱛᱮ ᱵᱟᱝ ᱢᱟᱱᱟᱣᱜᱼᱟ (ᱴᱨᱟᱱᱥᱯᱚᱨᱴᱟᱨ ᱞᱟᱹᱜᱤᱫ ₹35,000)᱾ ᱛᱚᱵᱮ ᱦᱚᱸ ᱥᱮᱣ ᱢᱮ?",
