  "g3.formh": "ᱥᱮᱣ ᱟᱠᱟᱱ ᱵᱤᱞ ᱠᱷᱚᱱ ᱟᱸᱠᱰᱟ ᱥᱟᱦᱴᱟ ᱟᱠᱟᱱᱟ᱾ ᱪᱮᱫ ᱯᱮᱴᱷᱟ ᱦᱚᱸ ᱨᱮ ᱚᱪᱚ ᱢᱮ, ᱩᱫᱟᱹᱞ ᱞᱟᱹᱜᱤᱫ GSTR-2B ᱨᱮ ᱧᱮᱞ ᱠᱟᱱ ITC᱾ ᱵᱚᱫᱚᱞ ᱠᱟᱱ ᱯᱮᱴᱷᱟ ᱪᱤᱱᱦᱟᱹ ᱟᱠᱟᱱᱟ᱾",
  "g3.h.out": "3.1 ᱵᱟᱦᱨᱮ ᱥᱚᱯᱞᱟᱭ ᱟᱨ ᱨᱤᱵᱷᱟᱨᱥ ᱪᱟᱨᱡ ᱥᱚᱯᱞᱟᱭ ᱨᱮᱭᱟᱜ ᱴᱮᱠᱥ",
  "g3.h.itc": "4(A) ᱢᱮᱱᱟᱜ ᱨᱮᱭᱟᱜ ᱤᱱᱯᱩᱴ ᱴᱮᱠᱥ ᱠᱨᱮᱰᱤᱴ",
  "g3.h.rev": "4(B) ᱨᱤᱵᱷᱟᱨᱥ ᱟᱠᱟᱱ ᱤᱱᱯᱩᱴ ᱴᱮᱠᱥ ᱠᱨᱮᱰᱤᱴ",
  "g3.h.exin": "5 ᱪᱷᱚᱴ, ᱱᱤᱞ ᱟᱨ GST ᱵᱟᱝ ᱵᱷᱤᱛᱤᱨ ᱥᱚᱯᱞᱟᱭ",
  "g3.h.more": "ᱥᱟᱹᱜᱟᱹᱭ ᱟᱠᱟᱱ ᱠᱨᱮᱰᱤᱴ, ᱥᱩᱫ ᱟᱨ ᱯᱟᱧᱡᱟᱭ ᱯᱷᱤᱥ",
